//! Independent whole original registration, over immutable input-only corpus.
pub use dq_analyze::{lint,sem,gens,tree};pub use dq_analyze::original_policy_descriptors as allow_registry_fields;
#[path="../fixtures/original_policies/setter_publishes.rs"]mod original;
#[path="../fixtures/native-setter-publishes/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
fn main()->Result<(),Box<dyn std::error::Error>>{for(case,body)in fixture::CASES{let root=scratch::dir(&format!("setter-whole-original-{case}"));for(path,text)in fixture::files(case,body){let path=root.join(path);std::fs::create_dir_all(path.parent().unwrap())?;std::fs::write(path,text)?;}let mut registry=lint::Registry::default();original::register(&mut registry);let engine=dq_analyze::run::Engine::new(registry,dq_analyze::run::Options{root:root.clone(),lints:vec!["setter_publishes".into()],no_cache:true,raw:true,..Default::default()})?;let sem=sem::sem_for(&engine.tree).ok_or("actual Original model unavailable")?;if !sem.errors.is_empty(){return Err(format!("actual Original fixture {case}: {:?}",sem.errors).into())}let out=engine.run_one(engine.reg.lints[0].as_ref());println!("SETTER_WHOLE_ORIGINAL={}",serde_json::json!({"case":case,"sites":out.run.sites,"notes":out.run.notes,"allow_used":out.allow_used,"failed":out.failed,"text":out.text,"internal_error":out.internal_error}));}Ok(())}
